<?php
namespace Tests\Feature;
use App\Models\Branch;use App\Models\Customer;use App\Models\Organization;use App\Models\OutboundMessage;use App\Models\User;use App\Services\CommunicationService;use Illuminate\Auth\Notifications\ResetPassword;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Notification;use Illuminate\Support\Str;use Tests\TestCase;
class AuthRecoveryTest extends TestCase{use RefreshDatabase;
 public function test_login_is_clean_and_has_forgotten_password():void{$this->get(route('login'))->assertOk()->assertSee('Glemt passord?')->assertDontSee('test</b> / <b>test',false);}
 public function test_real_user_can_request_reset_without_account_enumeration():void{Notification::fake();$user=User::factory()->create(['email'=>'real@example.no']);$this->post(route('password.email'),['email'=>$user->email])->assertRedirect()->assertSessionHas('status');Notification::assertSentTo($user,ResetPassword::class);$this->post(route('password.email'),['email'=>'unknown@example.no'])->assertRedirect()->assertSessionHas('status');}
 public function test_demo_and_dummy_data_never_queue_or_send_messages():void{Notification::fake();$org=Organization::create(['public_id'=>Str::uuid(),'name'=>'Demo','organization_number'=>'DEMO-DEKKPILOT']);$branch=Branch::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'name'=>'Hoved','code'=>'H']);$user=User::factory()->create(['organization_id'=>$org->id,'branch_id'=>$branch->id,'email'=>'demo@dekkpilot.no']);$customer=Customer::create(['public_id'=>Str::uuid(),'organization_id'=>$org->id,'branch_id'=>$branch->id,'customer_number'=>'D1','name'=>'Demo Kunde','email'=>'demo.customer@example.no','notes'=>'[DUMMY] Visningsdata']);$this->post(route('password.email'),['email'=>$user->email])->assertSessionHas('status');Notification::assertNothingSent();$message=app(CommunicationService::class)->queue($org->id,$customer,'email',$customer->email,'Test','Skal ikke sendes');$this->assertSame('cancelled',$message->status);$this->assertStringContainsString('aldri eksternt',$message->last_error);}
}
